// --- prototypes generated by arduino_sim.py (the Arduino IDE/Tinkercad do the same) ---
void setup();
void loop();
// ex08 -- two tasks in one loop(): a counter task and an LED task, each with its own timer
const int LED = 12;
const unsigned long PRODUCT_INTERVAL = 3000;
const unsigned long LED_INTERVAL = 500;
const int MAX_PRODUCTS = 20;

unsigned long prevProduct = 0, prevLed = 0;
int counter = 0;
bool ledOn = false;

void setup() {
  pinMode(LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  unsigned long now = millis();

  // task 1: production counter, stops at 20 but never blocks the loop
  if (counter < MAX_PRODUCTS && now - prevProduct >= PRODUCT_INTERVAL) {
    prevProduct = now;
    counter++;
    Serial.print("Product produced : ");
    Serial.println(counter);
  }

  // task 2: LED, fully independent
  if (now - prevLed >= LED_INTERVAL) {
    prevLed = now;
    ledOn = !ledOn;
    digitalWrite(LED, ledOn);
  }
}
